import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";
import "../styles/UserGig.css";

const UserGig = () => {
  const { gigId } = useParams();
  const [gig, setGig] = useState(null);
  const [loggedInUser, setLoggedInUser] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchGig = async () => {
      try {
        const res = await axios.get(`http://localhost:5000/api/gigs/${gigId}`);
        console.log("🎸 GIG RESPONSE:", res.data);
        setGig(res.data);
      } catch (err) {
        console.error("❌ Error fetching gig:", err);
      }
    };

    const storedUser = localStorage.getItem("user");
    if (storedUser) {
      try {
        const parsedUser = JSON.parse(storedUser);
        console.log("👤 Logged-in user:", parsedUser);
        setLoggedInUser(parsedUser);
      } catch (err) {
        console.error("❌ Error parsing logged-in user:", err);
      }
    }

    fetchGig();
  }, [gigId]);

  const handleApply = async () => {
    if (!gig || !loggedInUser) {
      alert("You're missing user or gig info.");
      return;
    }

    const applicantData = {
      gigId: gig._id,
      posterUserId: gig.userId,
      posterUsername: gig.username,
      title: gig.title,
      applicantUserId: loggedInUser._id,
      applicantUsername: loggedInUser.username,
    };

    console.log("📤 Submitting applicant data:", applicantData);

    try {
      const res = await axios.post("http://localhost:5000/api/applicants", applicantData);
      alert("✅ Applied successfully!");
    } catch (error) {
      console.error("❌ Error submitting application:", error.response?.data || error);
      alert("❌ Error submitting application.");
    }
  };

  if (!gig) return <div>Loading...</div>;

  return (
    <div className="profile-container">
      <h2 className="profile-title">Gig Posting</h2>

      <div className="form-group">
        <label>Title</label>
        <input value={gig.title} readOnly />
      </div>
      <div className="form-group">
        <label>Gig Type</label>
        <input value={gig.gigType} readOnly />
      </div>
      <div className="form-group">
        <label>Genre</label>
        <input value={Array.isArray(gig.genre) ? gig.genre.join(", ") : gig.genre} readOnly />
      </div>
      <div className="form-group">
        <label>City</label>
        <input value={gig.city} readOnly />
      </div>
      <div className="form-group">
        <label>Description</label>
        <textarea value={gig.description} readOnly />
      </div>
      <div className="form-group">
        <label>Date Posted</label>
        <input value={gig.postingDate?.split("T")[0]} readOnly />
      </div>
      <div className="form-group">
        <label>Expires</label>
        <input value={gig.expiryDate?.split("T")[0]} readOnly />
      </div>
      <div className="form-group">
        <label>Posted By</label>
        <input value={gig.username || "Unknown"} readOnly />
      </div>

      <button
        className="view-profile-button"
        onClick={() => {
          navigate(`/user-view-profile/${gig.userId}`);
        }}
      >
        View User Profile
      </button>

      <button className="apply-button" onClick={handleApply}>
        Apply To This Gig
      </button>
    </div>
  );
};

export default UserGig;
